PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

// Thread block tile dimensions
.visible .entry bmm_fp16(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 batch,
    .param .u32 M,
    .param .u32 K,
    .param .u32 N
)
{
    // ---------------------------------
    // Register declarations
    // ---------------------------------
    .reg .pred   %p<4>;
    .reg .b32    %r<20>;
    .reg .b64    %rd<20>;
    .reg .f32    %f<4>;
    .reg .f16    %h<2>;

    // ---------------------------------
    // Load kernel arguments
    // ---------------------------------
    ld.param.u64    %rd1, [A_ptr];
    ld.param.u64    %rd2, [B_ptr];
    ld.param.u64    %rd3, [C_ptr];
    ld.param.u32    %r1,  [batch];
    ld.param.u32    %r2,  [M];
    ld.param.u32    %r3,  [K];
    ld.param.u32    %r4,  [N];

    // ---------------------------------
    // Compute indices
    // ---------------------------------
    // blockIdx.{x,y,z}
    mov.u32 %r5, %ctaid.x;   // tile column
    mov.u32 %r6, %ctaid.y;   // tile row
    mov.u32 %r7, %ctaid.z;   // batch index

    // threadIdx.{x,y}
    mov.u32 %r8, %tid.x;     // thread column within tile
    mov.u32 %r9, %tid.y;     // thread row within tile

    // Global row = tile_row * TILE_M + thread_row
    // Global col = tile_col * TILE_N + thread_col
    .const .u32 TILE_M = 16;
    .const .u32 TILE_N = 16;

    mul.lo.u32   %r10, %r6, TILE_M;
    add.u32      %r10, %r10, %r9;   // row index

    mul.lo.u32   %r11, %r5, TILE_N;
    add.u32      %r11, %r11, %r8;   // col index

    // Guard against out‑of‑bounds
    setp.ge.u32 %p0, %r10, %r2;    // row >= M ?
    setp.ge.u32 %p1, %r11, %r4;    // col >= N ?
    or.pred      %p2, %p0, %p1;
    @%p2 bra     DONE;            // exit if OOB

    // ---------------------------------
    // Compute base pointers for this batch
    // ---------------------------------
    // offset_A = batch * M * K
    mul.wide.u32 %rd4, %r7, %r2;        // batch * M
    mul.wide.u32 %rd5, %rd4, %r3;       // batch * M * K
    mul.wide.u32 %rd6, %r10, %r3;       // row * K
    add.u64      %rd7, %rd5, %rd6;      // batch_offset + row_offset

    // offset_B = batch * K * N
    mul.wide.u32 %rd8, %r7, %r3;        // batch * K
    mul.wide.u32 %rd9, %rd8, %r4;       // batch * K * N
    mul.wide.u32 %rd10, %r11, 2;        // col * sizeof(half) = col*2
    // We'll add col offset inside the loop per element

    // offset_C = batch * M * N
    mul.wide.u32 %rd11, %r7, %r2;       // batch * M
    mul.wide.u32 %rd12, %rd11, %r4;     // batch * M * N
    mul.wide.u32 %rd13, %r10, %r4;      // row * N
    add.u64      %rd14, %rd12, %rd13;   // batch_offset + row_offset

    // ---------------------------------
    // Initialize accumulator (fp32)
    // ---------------------------------
    mov.f32 %f0, 0.0;

    // ---------------------------------
    // Loop over K dimension
    // ---------------------------------
    .reg .u32 %r_k;
    mov.u32 %r_k, 0;

LOOP_K:
    setp.ge.u32 %p3, %r_k, %r3;
    @%p3 bra END_LOOP;

    // Load A element: A[batch, row, k]
    // address = A_ptr + (batch_offset + row*K + k) * 2
    mul.wide.u32 %rd15, %r_k, 2;          // k * sizeof(half)
    add.u64      %rd16, %rd1, %rd7;       // base A + batch+row offset
    add.u64      %rd16, %rd16, %rd15;     // final address
    ld.global.u16 %r12, [%rd16];
    // Convert half to float
    mov.b16 %h0, %r12;
    cvt.f32.f16 %f1, %h0;

    // Load B element: B[batch, k, col]
    // address = B_ptr + (batch*K*N + k*N + col) * 2
    mul.wide.u32 %rd17, %r_k, %r4;        // k * N
    mul.wide.u32 %rd17, %rd17, 2;        // *2 => bytes
    add.u64      %rd18, %rd2, %rd9;       // base B batch offset
    add.u64      %rd18, %rd18, %rd17;     // + k*N*2
    add.u64      %rd18, %rd18, %rd10;     // + col*2
    ld.global.u16 %r13, [%rd18];
    mov.b16 %h1, %r13;
    cvt.f32.f16 %f2, %h1;

    // Multiply-accumulate
    fma.rn.f32 %f0, %f1, %f2, %f0;

    // k++
    add.u32 %r_k, %r_k, 1;
    bra LOOP_K;

END_LOOP:
    // Convert accumulator back to half
    cvt.rn.f16.f32 %h2, %f0;
    // Store to C
    // address = C_ptr + (batch_offset + row*N + col) * 2
    mul.wide.u32 %rd19, %r11, 2;         // col*2
    add.u64      %rd20, %rd3, %rd14;     // base C + batch+row offset
    add.u64      %rd20, %rd20, %rd19;    // final address
    st.global.u16 [%rd20], %h2;

DONE:
    ret;
}
