# ModelNew class that uses the PTX harness to launch the kernel
# -------------------------------------------------------------
class ModelNew:
    def __init__(self):
        # Load PTX module via the provided harness
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Batched matrix multiplication using the custom PTX kernel.
        A: (batch, m, k) fp16 tensor on CUDA
        B: (batch, k, n) fp16 tensor on CUDA
        Returns C: (batch, m, n) fp16 tensor on CUDA
        """
        assert A.is_cuda and B.is_cuda, "Inputs must be CUDA tensors"
        assert A.dtype == torch.float16 and B.dtype == torch.float16, "Inputs must be fp16"
        batch, m, k = A.shape
        _, _, n = B.shape

        # Allocate output tensor
        C = torch.empty(batch, m, n, dtype=torch.float16, device='cuda')

        # Kernel launch configuration
        TILE_M = 16
        TILE_N = 16
        grid_x = (n + TILE_N - 1) // TILE_N
        grid_y = (m + TILE_M - 1) // TILE_M
        grid_z = batch
        grid = (grid_x, grid_y, grid_z)

        block = (TILE_N, TILE_M, 1)   # 256 threads per block

        # Prepare argument list for the PTX harness
        args = [
            A.data_ptr(),
            B.data_ptr(),
            C.data_ptr(),
            batch,
            m,
            k,
            n,
        ]

        # Launch the kernel
        ptx_launch(self.module, "bmm_fp16", grid, block, args)

        return C
